document.addEventListener('DOMContentLoaded', function() {
                // Attach click handler to the purge cache button in admin bar
                var adminBarBtn = document.getElementById('wp-admin-bar-xcloud-cloudflare-cache-purge');
                if (adminBarBtn) {
                    adminBarBtn.addEventListener('click', function(e) {
                        e.preventDefault();
                        xCloudPurgeCache('admin-bar');
                        return false;
                    });
                }

                // Attach click handler to the purge cache button on the settings page
                var settingsBtn = document.getElementById('xcloud-purge-cache-button');
                if (settingsBtn) {
                    settingsBtn.addEventListener('click', function(e) {
                        e.preventDefault();
                        xCloudPurgeCache('settings-page');
                        return false;
                    });
                }
            });

            function xCloudPurgeCache(source) {
                // Determine if this was triggered from the admin bar
                var fromAdminBar = source === 'admin-bar';

                if (!confirm('Are you sure you want to purge the entire Cloudflare cache?')) {
                    return false;
                }

                // Add console logging for debugging
                console.log('Purging Cloudflare cache...');

                // Function to show notice — uses WP admin styles in wp-admin, self-styled toast on frontend
                function showAdminNotice(type, message) {
                    // Remove any existing notices first
                    document.querySelectorAll('.xcloud-cloudflare-notice').forEach(function(el) {
                        el.remove();
                    });

                    var isAdmin = document.body.classList.contains('wp-admin');

                    if (isAdmin) {
                        // WP Admin: use native notice styles
                        var noticeTypeClass = { success: 'notice-success', error: 'notice-error', info: 'notice-info' };
                        var noticeClass = 'notice ' + (noticeTypeClass[type] || 'notice-info') + ' is-dismissible xcloud-cloudflare-notice';
                        var notice = document.createElement('div');
                        notice.className = noticeClass;

                    // Use textContent — message may contain server-supplied text; avoid XSS via innerHTML
                        var noticeMessage = document.createElement('p');
                        noticeMessage.textContent = message;
                        notice.appendChild(noticeMessage);

                    // Add dismiss button
                        var dismissBtn = document.createElement('button');
                        dismissBtn.type = 'button';
                        dismissBtn.className = 'notice-dismiss';
                        var srSpan = document.createElement('span');
                        srSpan.className = 'screen-reader-text';
                        srSpan.textContent = 'Dismiss this notice.';
                        dismissBtn.appendChild(srSpan);
                        dismissBtn.addEventListener('click', function() { notice.remove(); });
                        notice.appendChild(dismissBtn);

                        var h1 = document.querySelector('.wrap > h1');
                        if (h1) {
                            h1.parentNode.insertBefore(notice, h1.nextSibling);
                        } else {
                            var wpbody = document.getElementById('wpbody-content');
                            if (wpbody) {
                                wpbody.insertBefore(notice, wpbody.firstChild);
                            } else if (document.body) {
                                document.body.insertBefore(notice, document.body.firstChild);
                            }
                        }
                    } else {
                        // Frontend: self-styled fixed toast notification
                        var colorMap = { success: '#00a32a', error: '#d63638', info: '#72aee6' };
                        var bgMap = { success: '#f0f6f1', error: '#fcf0f1', info: '#f0f6fc' };
                        var borderColor = colorMap[type] || colorMap.info;
                        var bgColor = bgMap[type] || bgMap.info;

                        var toast = document.createElement('div');
                        toast.className = 'xcloud-cloudflare-notice';
                        toast.style.cssText = 'position:fixed;top:46px;right:16px;z-index:100001;max-width:380px;padding:12px 40px 12px 16px;background:' + bgColor + ';border-left:4px solid ' + borderColor + ';border-radius:4px;box-shadow:0 2px 8px rgba(0,0,0,0.15);font:14px/1.5 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;color:#1e1e1e;opacity:0;transition:opacity 0.3s ease;';

                        var msgSpan = document.createElement('span');
                        msgSpan.textContent = message;
                        toast.appendChild(msgSpan);

                        var closeBtn = document.createElement('button');
                        closeBtn.type = 'button';
                        closeBtn.setAttribute('aria-label', 'Dismiss');
                        closeBtn.style.cssText = 'position:absolute;top:8px;right:8px;background:none;border:none;font-size:18px;cursor:pointer;color:#666;line-height:1;padding:0;';
                        closeBtn.textContent = '\u00d7';
                        closeBtn.addEventListener('click', function() { toast.remove(); });
                        toast.appendChild(closeBtn);

                        document.body.appendChild(toast);
                        // Trigger fade-in
                        requestAnimationFrame(function() { toast.style.opacity = '1'; });

                        // Auto-dismiss after 5 seconds for success/info
                        if (type !== 'error') {
                            setTimeout(function() {
                                toast.style.opacity = '0';
                                setTimeout(function() { toast.remove(); }, 300);
                            }, 5000);
                        }
                    }
                }

                // Update status div if we're on the settings page
                var statusDiv = document.getElementById('xcloud-cache-status');

                console.log('Sending AJAX request...');
                if (statusDiv !== null) {
                    var loadingP = document.createElement('p');
                    loadingP.textContent = 'Purging cache...';
                    statusDiv.replaceChildren(loadingP);
                }
                // Show loading notice if from admin bar
                if (fromAdminBar) {
                    showAdminNotice('info', 'Purging Cloudflare cache...');
                }

                var formData = new FormData();
                formData.append('action', 'xcloud_purge_cloudflare_cache');
                formData.append('nonce', xcloud_ajax.nonce);

                fetch(xcloud_ajax.ajaxurl, {
                    method: 'POST',
                    body: formData
                })
                .then(function(res) {
                    var contentType = res.headers.get('content-type') || '';
                    if (!res.ok) {
                        throw new Error('Server returned HTTP ' + res.status);
                    }
                    if (contentType.indexOf('application/json') === -1) {
                        throw new Error('Unexpected response from server (non-JSON)');
                    }
                    return res.json();
                })
                .then(function(response) {
                    console.log('AJAX response received:', response);
                    if (response.success) {
                        if (statusDiv !== null) {
                            var successP = document.createElement('p');
                            successP.className = 'notice notice-success';
                            successP.textContent = 'Cache purged successfully!';
                            statusDiv.replaceChildren(successP);
                        }
                        if (fromAdminBar) {
                            showAdminNotice('success', 'Cloudflare cache purged successfully!');
                        }
                    } else {
                        var errorMsg = response.data || 'Unknown error';
                        if (statusDiv !== null) {
                            var errorP = document.createElement('p');
                            errorP.className = 'notice notice-error';
                            errorP.textContent = 'Error: ' + errorMsg;
                            statusDiv.replaceChildren(errorP);
                        }
                        if (fromAdminBar) {
                            showAdminNotice('error', 'Error purging Cloudflare cache: ' + errorMsg);
                        }
                    }
                })
                .catch(function(error) {
                    console.error('Fetch error:', error);
                    var errMsg = error.message || 'Could not connect to the server.';
                    if (statusDiv !== null) {
                        var connErrorP = document.createElement('p');
                        connErrorP.className = 'notice notice-error';
                        connErrorP.textContent = 'Error: ' + errMsg;
                        statusDiv.replaceChildren(connErrorP);
                    }
                    if (fromAdminBar) {
                        showAdminNotice('error', 'Error purging Cloudflare cache: ' + errMsg);
                    }
                });

                return false;
            }

